      const r2Min = (targetZ - TAKEOFF.z + TASK.startOffset - 0.001501) / (2 * TASK.startOffset);
      const r2Max = (targetZ - TAKEOFF.z + TASK.startOffset + 0.001501) / (2 * TASK.startOffset);
