      }
      return -1;
    }

    const t0 = Date.now();
    for (const s of [0, 1, 5, 101, 102, 103, 104, 9999, 123456, 1500000]) {
      const obs = makeObs0(s);
      const found = findSeed(obs);
      if (found !== s) console.error("Mismatch:", s, found);
    }
    console.log("All matched! Elapsed for 10 searches:", Date.now() - t0, "ms");
  });
});
